import{_ as a,o as t,c as n,a2 as e}from"./chunks/framework.B4hAkGey.js";const u=JSON.parse('{"title":"EP.08 WebRTC 直播 vs 传统 RTMP","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.08-live-vs-rtmp.md","filePath":"comics/EP.08-live-vs-rtmp.md","lastUpdated":1792683941000}'),i={name:"comics/EP.08-live-vs-rtmp.md"};function l(p,s,o,r,d,c){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="ep-08-webrtc-直播-vs-传统-rtmp" tabindex="-1">EP.08 WebRTC 直播 vs 传统 RTMP <a class="header-anchor" href="#ep-08-webrtc-直播-vs-传统-rtmp" aria-label="Permalink to &quot;EP.08 WebRTC 直播 vs 传统 RTMP&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/08-live-streaming/">模块八 · 直播场景的技术选型</a> 动手演示：Mediasoup SFU + ffmpeg 转推 RTMP 的完整 Demo</p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君的电商直播项目：现有 RTMP 推 CDN 支撑 10w+ 纯观看观众没问题，但老板要加<strong>连麦 PK</strong> 功能，RTMP 根本没有双向互动能力。</td></tr><tr><td>② 揭秘</td><td>码叔画出三种架构：方案 A 纯 RTMP（单向无互动）、方案 B 纯 WebRTC+SFU（互动但成本高）、方案 C <strong>混合架构</strong>（WebRTC 做互动层 + ffmpeg 转推 RTMP 给 CDN 做大规模分发）。</td></tr><tr><td>③ 实证</td><td>展示 Mediasoup SFU 接收主播 WebRTC 流，同时 fork 两路：一路给连麦观众（WebRTC 低延迟），一路通过 ffmpeg 转成 RTMP 推 CDN 给 10w 纯观看观众。</td></tr><tr><td>④ 结案</td><td>像素酱确认 WebRTC 和 RTMP 是互补而非竞争关系。码叔列三条坑点：SFU 成本算 simulcast 带宽、编码器必须开 simulcast、TURN 转发流量要预留预算。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-为什么-rtmp-做不了连麦" tabindex="-1">① 为什么 RTMP 做不了连麦？ <a class="header-anchor" href="#_1-为什么-rtmp-做不了连麦" aria-label="Permalink to &quot;① 为什么 RTMP 做不了连麦？&quot;">​</a></h3><p>RTMP 本质是一个<strong>单向推流协议</strong>——设计目标就是&quot;一个主播推给 N 个观众&quot;，没有&quot;观众把自己的流推回去&quot;的路径。HLS 更极端，直接把视频切片放 HTTP 服务器上，连实时性都牺牲了。</p><table tabindex="0"><thead><tr><th>协议</th><th>延迟</th><th>互动</th><th>分发规模</th><th>成本</th></tr></thead><tbody><tr><td>RTMP 推流 + CDN HLS 分发</td><td>3~10s</td><td>❌ 无</td><td>百万级</td><td>低（CDN 边缘缓存）</td></tr><tr><td>WebRTC + SFU</td><td>50~200ms</td><td>✅ 双向</td><td>万级</td><td>中高（SFU 服务器）</td></tr><tr><td>混合架构</td><td>互动 100ms / 观看 3s</td><td>✅ 混合</td><td>百万级</td><td>中（CDN + 部分 SFU）</td></tr></tbody></table><h3 id="_2-混合架构的完整链路" tabindex="-1">② 混合架构的完整链路 <a class="header-anchor" href="#_2-混合架构的完整链路" aria-label="Permalink to &quot;② 混合架构的完整链路&quot;">​</a></h3><p>这是当前主流直播平台（抖音、快手、B站、Twitch）都在用的架构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主播（手机/网页）</span></span>
<span class="line"><span>  │ WebRTC（带 simulcast 3 层）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>SFU 服务器（Mediasoup / Janus / Pion）</span></span>
<span class="line"><span>  ├─▶ 连麦观众 A（WebRTC 拉最低可用层，~100ms）</span></span>
<span class="line"><span>  ├─▶ 连麦观众 B（WebRTC 拉中等层，~100ms）</span></span>
<span class="line"><span>  ├─▶ 连麦嘉宾 C（WebRTC 拉最高层，~100ms）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─▶ ffmpeg 子进程（从 SFU 的本地录制端口读取流）</span></span>
<span class="line"><span>        │ RTMP</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>        CDN 推流节点</span></span>
<span class="line"><span>          │ HLS/DASH</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>          10w+ 纯观看观众（延迟 ~3s）</span></span></code></pre></div><p><strong>关键实现细节</strong>：SFU 需要把多路 WebRTC Producer 聚合成一条，编码成 RTMP 推给 CDN。常用方式：</p><ol><li><strong>SFU 内置转推</strong>：Mediasoup 的 <code>record()</code> API / Janus 的录制模块</li><li><strong>ffmpeg + SRT</strong>：SFU 暴露 SRT 接收端口，ffmpeg <code>-i srt://sfu-host:9000</code> 再转 RTMP</li><li><strong>录屏桥接</strong>：用一个&quot;虚拟观众&quot;身份连接 SFU，拿到流后交给 ffmpeg（hack 但有效）</li></ol><h3 id="_3-simulcast-为什么是-sfu-必需" tabindex="-1">③ Simulcast 为什么是 SFU 必需？ <a class="header-anchor" href="#_3-simulcast-为什么是-sfu-必需" aria-label="Permalink to &quot;③ Simulcast 为什么是 SFU 必需？&quot;">​</a></h3><p><strong>Simulcast</strong> = 编码器同时输出多路不同分辨率/码率的视频流：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 主播端：Chrome 自动开 simulcast（VP8/VP9）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sender</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pc.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addTrack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(track, stream);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// SFU 会拿到 3 路 track：180p / 360p / 720p</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 然后按观众带宽发不同层</span></span></code></pre></div><p>不开 simulcast 的后果：</p><ul><li>编码器只输出<strong>一路最高码率</strong>的流</li><li>SFU 必须给所有观众转发这一路</li><li>弱网观众：卡成 PPT（带宽不够）</li><li>SFU 必须硬转码才能适配不同观众 → <strong>CPU 炸了</strong>（转码成本是转发的 10~100 倍）</li></ul><blockquote><p>H264 的 simulcast 需要用 SVC（Scalable Video Coding），Chrome 的 H264 默认不支持 SVC，VP8/VP9 原生支持 simulcast。<strong>生产环境建议主播端用 VP9 编码</strong>，SFU 端按需转 H264 给 CDN。</p></blockquote><h3 id="_4-turn-流量成本估算" tabindex="-1">④ TURN 流量成本估算 <a class="header-anchor" href="#_4-turn-流量成本估算" aria-label="Permalink to &quot;④ TURN 流量成本估算&quot;">​</a></h3><p>不是所有用户都能走 P2P 直连——对称 NAT 或企业防火墙后面的用户必须走 TURN 中继。估算公式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TURN 流量 = 连麦人数 × 平均码率 × 2（上下行）× 0.25（假设 25% 走 TURN）</span></span></code></pre></div><p>举例：1000 人连麦，平均上行 2Mbps、下行 4Mbps：</p><ul><li>总 TURN 带宽 ≈ 1000 × (2+4) × 0.25 = <strong>1500 Mbps</strong></li><li>月流量 ≈ 1500 × 3600 × 24 × 30 / 8 ≈ <strong>20 TB</strong></li></ul><p>云厂商 TURN 中继价格：$0.08~$0.15 / GB，<strong>约 $1600~$3000 / 月</strong>。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：能不能让 RTMP 也支持互动？</strong> 不能。RTMP 是单向推送设计。有人尝试过 RTMP 拉流回推主播（&quot;连麦&quot;），但延迟至少 3~5s，实际体验就是&quot;你喊了对方半秒才听到&quot;。</li><li><strong>Q：SFU 选 Mediasoup 还是 Janus？</strong> Mediasoup 性能更好（纯 Node.js + C++ addon，单核 5000 并发），Janus 功能更全（内置录制、转码、插件系统）。<strong>国内直播平台大多用 Mediasoup</strong>，Janus 在开源社区更火。</li><li><strong>Q：ffmpeg 转 RTMP 会丢帧吗？</strong> 不会（用 <code>-c:v copy -c:a copy</code> 直接 copy）。但如果从 WebRTC 的 VP8/VP9 转 H264（CDN 要求 H264），需要硬编码——记得加 <code>-preset veryfast -tune zerolatency</code> 控制延迟在 500ms 内。</li><li><strong>Q：CDN 支持 WebRTC 吗？</strong> 新兴 CDN 比如 Cloudflare Stream、阿里云 RTC、腾讯云 TRTC 都原生支持 WebRTC 分发。传统 CDN（网宿、七牛）主要做 HLS/DASH，但也在加速 WebRTC 支持。</li><li><strong>Q：10w+ 连麦观众怎么办？</strong> 连麦人数一般不会超过 100~500 人（体验限制）。超过 1000 人连麦就要用<strong>分层 SFU</strong>（中心 SFU 接边缘 SFU，边缘 SFU 接终端），或者让&quot;观众&quot;降级为纯观看，只保留主播和 TOP N 嘉宾用 WebRTC。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>你的直播产品需求：1w 纯观看观众 + 10 人连麦 PK。用纯 RTMP 方案行得通吗？为什么？给出正确架构。</li><li>什么是 simulcast？SFU 为什么必须依赖它？如果主播端编码器不开 simulcast，会发生什么？</li><li>估算：1000 人连麦的直播间，平均码率上行 2Mbps、下行 4Mbps，假设 25% 用户走 TURN 中继，你需要预留多少 TURN 带宽？</li></ol><details><summary>答案</summary><ol><li>纯 RTMP 方案<strong>完全不行</strong>——RTMP 是单向推流协议，没有观众上行推流的路径，连麦功能从根本上无法实现。正确架构：<strong>WebRTC + SFU 做连麦互动层 + ffmpeg 从 SFU 转推 RTMP 给 CDN 做大规模分发</strong>。主播用 WebRTC 推流到 SFU，10 个连麦嘉宾也用 WebRTC 接 SFU，SFU 同时把混合后的流转成 RTMP 推给 CDN 供 1w 纯观看用户通过 HLS/DASH 消费。</li><li>Simulcast 是视频编码器同时输出多路不同分辨率/码率的视频流（如 180p / 360p / 720p）。SFU 依赖 simulcast 来给不同网络条件的观众发不同码率层级——带宽好的发高层，带宽差的发低层。如果主播端不开 simulcast，SFU 只能给所有观众转发<strong>最高码率那一路</strong>，弱网观众卡成 PPT，SFU 只能被迫在服务端硬转码（CPU 成本是转发的 10~100 倍），生产环境撑不住。</li><li>TURN 带宽 = 连麦人数 × 平均总码率（上行+下行）× TURN 比例 = 1000 × (2 + 4) × 0.25 = <strong>1500 Mbps</strong>。如果每人 8 小时连麦，月流量约 1500 Mbps × 3600s × 8h × 30d / 8 = 162 TB，云厂商成本约 $13,000~$24,000/月——这就是为什么 TURN 成本必须提前算进预算。</li></ol></details>`,30)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
